    /// <summary>Every typed record chunk, by id (for the theory-driven chunk tests).</summary>
    public static IRflSectionContent Chunk(SectionType type) => type switch
    {
        SectionType.AlpineWeatherRegions => WeatherRegions(),
        SectionType.AlpineVehicleFactories => VehicleFactories(),
        SectionType.AlpineProjectionCameras => ProjectionCameras(),
        SectionType.AlpineRopeEmitters => RopeEmitters(),
        SectionType.AlpineDirectionalLights => DirectionalLights(),
        SectionType.AlpineWaypointHelpers => WaypointHelpers(),
        SectionType.AlpineMoverPaths => MoverPaths(),
        SectionType.AlpineLiquidEmission => LiquidEmission(),
        _ => throw new ArgumentOutOfRangeException(nameof(type)),
    };

    public static readonly SectionType[] RecordChunks =
    {
        SectionType.AlpineWeatherRegions, SectionType.AlpineVehicleFactories, SectionType.AlpineProjectionCameras,
        SectionType.AlpineRopeEmitters, SectionType.AlpineDirectionalLights, SectionType.AlpineWaypointHelpers,
        SectionType.AlpineMoverPaths, SectionType.AlpineLiquidEmission,
    };

    public static byte[] Bytes(IRflSectionContent content)
    {
        var w = new RfWriter();
        content.Write(w, new RflContext(RflFile.AlpineSaveVersion));
        return w.ToArray();
    }

    /// <summary>
    /// A version-2 Alpine lightmap section (alpine_lightmap.h layout): 3 surface charts (2 charted), a movers table,
    /// a terrain table, an overflow table, a table with an unknown tag, the tile table, one zlib-compressed raw RGB8 layer.
    /// </summary>
    public static byte[] LightmapSection(uint version = 2)
    {
        using var ms = new MemoryStream();
        using var w = new BinaryWriter(ms);
        var tables = new List<(uint Tag, byte[] Body, uint Tiles)>
        {
            (1, Table(b => { b.Write(1u); b.Write(77); b.Write(1u); b.Write(0x12345678u); b.Write((ushort)1); b.Write((ushort)1); b.Write((ushort)8); b.Write((ushort)8); }), 1),
            (2, Table(b => { b.Write(1u); b.Write(9801); b.Write((ushort)64); b.Write((ushort)64); b.Write(0f); b.Write(0f); b.Write(0.5f); b.Write(0xABCDEF0123456789ul); }), 1),
            (3, Table(b => { b.Write(1u); b.Write(2u); b.Write(10u); b.Write(0u); b.Write(0x1111ul); b.Write(2u); b.Write((ushort)16); b.Write((ushort)16); for (int i = 0; i < 9; i++) { b.Write(0f); } b.Write(0.25f); b.Write((byte)1); b.Write((byte)2); b.Write((byte)3); b.Write((byte)0); b.Write(4u); b.Write(5u); }), 1),
            (99, Table(b => b.Write(0xDEADBEEFu)), 0),
        };
        uint surfaceTiles = 2;
        uint tiles = surfaceTiles + (uint)tables.Sum(t => (int)t.Tiles);
        const int pages = 1;
        int payload = 256 * 256 * 3 * pages;
        byte[] stored = Convert.FromBase64String(ZeroPageZlib); // fixed bytes: zlib output is not stable across runtimes

        w.Write(version);
        w.Write(0u); // flags
        w.Write((ushort)256);
        w.Write((ushort)244);
        w.Write((byte)4);
        w.Write((byte)8);
        w.Write((byte)7);
        w.Write((byte)0);
        w.Write((ushort)pages);
        w.Write(3u); // charts
        w.Write(tiles);
        w.Write(12u); // src faces
        w.Write(3u); // src surfaces
        w.Write(0x0BADF00Du);
        w.Write((ushort)1); w.Write((ushort)1);
        w.Write((ushort)0); w.Write((ushort)0);
        w.Write((ushort)2); w.Write((ushort)3);
        w.Write((uint)tables.Count);
        foreach ((uint tag, byte[] body, uint t) in tables)
        {
            w.Write(tag);
            w.Write((ushort)1);
            w.Write((ushort)0);
            w.Write((uint)body.Length);
            w.Write(t);
            w.Write(body);
        }

        for (int i = 0; i < tiles; i++)
        {
            w.Write((ushort)0);
            w.Write((ushort)(i * 8));
            w.Write((ushort)0);
        }

        w.Write((byte)1);
        w.Write(new byte[3]);
        w.Write((ushort)0); // radiance_ldr
        w.Write((ushort)0); // raw_rgb8
        w.Write((ushort)1);
        w.Write((byte)0); // rf_lightmap_x2
        w.Write((byte)1); // zlib
        w.Write((uint)payload);
        w.Write((uint)stored.Length);
        w.Write(stored);
        w.Flush();
        return ms.ToArray();
    }

    /// <summary>One black 256×256 raw RGB8 page (196 608 zero bytes), zlib-compressed once and pinned here.</summary>
    private const string ZeroPageZlib =
        "eNrtwTEBAAAAwqD1T+1pCaAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA" +
        "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA" +
        "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA4AYALQAB";

    /// <summary>
    /// An Alpine terrain chunk (alpine_terrain_reader.h:76-217 layout) with one terrain carrying overlays, a decoration and
    /// a build mapping; <paramref name="flags"/> lets a test set an unknown bit. The blob is opaque bytes (Glacier keeps it raw).
    /// </summary>
    public static byte[] TerrainSection(byte flags = 0x1B)
    {
        using var ms = new MemoryStream();
        using var w = new BinaryWriter(ms);
        w.Write(1u);
        w.Write(9801);
        w.Write(-64f); w.Write(0f); w.Write(-64f);
        Str(w, "hills");
        w.Write(2f);
        w.Write((ushort)65);
        w.Write((ushort)65);
        w.Write(-4f);
        w.Write(64f);
        w.Write((byte)32);
        w.Write((byte)2);
        w.Write((byte)2);
        w.Write(flags);
        w.Write(16f);
        w.Write(8f);
        Str(w, "Rck_default.tga");
        Str(w, string.Empty);
        w.Write((byte)2);
        Str(w, "grass.tga"); w.Write(4f); w.Write((byte)0);
        Str(w, "rock.tga"); w.Write(8f); w.Write((byte)1);
        if ((flags & 0x08) != 0)
        {
            w.Write((byte)1);
            Str(w, "moss.tga"); w.Write(2f); w.Write((byte)2);
        }

        if ((flags & 0x10) != 0)
        {
            w.Write((byte)1);
            Str(w, "bush.v3m"); w.Write(0.5f); w.Write(1f); w.Write(1.5f); w.Write(35f); w.Write(80f); w.Write(0f); w.Write((byte)0xFF); w.Write((byte)0x2);
        }

        w.Write(4u);
        for (int i = 0; i < 4; i++)
        {
            w.Write(100 + i);
            w.Write(1089u);
            w.Write(0x9E3779B97F4A7C15ul * (ulong)(i + 1));
        }

        byte[] blob = Enumerable.Range(0, 40).Select(i => (byte)i).ToArray();
        w.Write(123456u);
        w.Write((uint)blob.Length);
        w.Write(blob);
        w.Flush();
        return ms.ToArray();
    }

    /// <summary>The whole synthetic v306 level (deterministic bytes).</summary>
    public static byte[] Level()
    {
        RflFile rfl = LevelTemplates.CreateNewRfl(FixedDate);

        // The new-level template already carries Alpine RED's new-level props chunk; give it non-default values.
        AlpineLevelPropertiesSection props = rfl.Sections.Select(s => s.Content).OfType<AlpineLevelPropertiesSection>().Single();
        props.EnableSun = 1;
        props.SunYaw = 30;
        props.SunPitch = 45;
        props.SunColorR = 255;
        props.SunColorG = 230;
        props.SunColorB = 200;
        props.NoShadowCastBrushUids.AddRange(new[] { 5, 6 });
        props.LightmapDensity = 16;
        props.MinimapEnabled = 1;
        props.MinimapBitmap = "synthetic_minimap.tga";
        props.MinimapWorldMin = new Vec3(-64, -8, -64);
        props.MinimapWorldMax = new Vec3(64, 32, 64);
        props.CameraFarClip = 500;

        var mesh = new AlpineMeshObjectsSection();
        mesh.Meshes.Add(new AlpineMeshObject
        {
            Uid = 9001_0, Position = new Vec3(0, 0, 5), Orientation = Mat3.Identity, ScriptName = "statue", MeshFilename = "statue.v3m",
            CollisionMode = 3, NoShadowCast = 1, BrushGeoSource = 2, CollisionMeshFilename = "statue_col.v3m", DrawScale = 1.5f,
        });
        rfl.InsertSection(new RflSection((uint)SectionType.AlpineMeshObjects, Array.Empty<byte>()) { Content = mesh, Dirty = true });

        foreach (SectionType t in RecordChunks)
        {
            rfl.InsertSection(new RflSection((uint)t, Array.Empty<byte>()) { Content = Chunk(t), Dirty = true });
        }

        rfl.InsertSection(new RflSection((uint)SectionType.AlpineTerrain, TerrainSection()));
        rfl.InsertSection(new RflSection((uint)SectionType.AlpineLightmaps, LightmapSection()));

        // A RED+ foreign chunk and a future Alpine chunk: both preserved raw, in place.
        rfl.InsertSection(new RflSection(0x5ED00001u, new byte[] { 1, 2, 3, 4, 5 }));
        rfl.InsertSection(new RflSection(0x0AFBAE20u, new byte[] { 9, 8, 7 }));
        return rfl.Save(updateTimestamp: false);
    }

    private static byte[] Table(Action<BinaryWriter> body)
    {
        using var ms = new MemoryStream();
        using (var w = new BinaryWriter(ms, System.Text.Encoding.Latin1, leaveOpen: true))
        {
            body(w);
        }

        return ms.ToArray();
    }

    private static void Str(BinaryWriter w, string s)
    {
        byte[] b = System.Text.Encoding.Latin1.GetBytes(s);
        w.Write((ushort)b.Length);
        w.Write(b);
    }
}
